code='''from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objects=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=bg and (r,c) not in seen:
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
         x,y=q.pop(); cells.append((x,y))
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          a,b=x+dx,y+dy
          if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
           seen.add((a,b)); q.append((a,b))
        rs=[x for x,y in cells]; cs=[y for x,y in cells]
        objects.append({'color':color,'cells':cells,'box':(min(rs),min(cs),max(rs),max(cs))})
    def holes(o):
     color,cells,(r0,c0,r1,c1)=o['color'],o['cells'],o['box']; s=set(cells); seen_h=set(); ans=[]
     for r in range(r0+1,r1):
      for c in range(c0+1,c1):
       if (r,c) not in s and (r,c) not in seen_h:
        q=[(r,c)]; seen_h.add((r,c)); comp=[]; edge=False
        while q:
         x,y=q.pop(); comp.append((x,y)); edge |= x in (r0,r1) or y in (c0,c1)
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          a,b=x+dx,y+dy
          if r0<=a<=r1 and c0<=b<=c1 and (a,b) not in s and (a,b) not in seen_h:
           seen_h.add((a,b)); q.append((a,b))
        if not edge: ans.append(comp)
     return ans
    def subset_sum(nums,target):
     reachable={0:[]}
     for i,n in enumerate(nums):
      for s,chosen in list(reachable.items()):
       if s+n<=target and s+n not in reachable: reachable[s+n]=chosen+[i]
     return reachable.get(target)
    target=None; chosen=None
    for o in objects:
     hs=holes(o); area=sum(map(len,hs))
     if not area: continue
     fillers=[x for x in objects if x is not o]
     pick=subset_sum([len(x['cells']) for x in fillers],area)
     if pick is not None:
      target=o; chosen=[fillers[i] for i in pick]; break
    color,cells,(r0,c0,r1,c1)=target['color'],target['cells'],target['box']; solid=set(cells)
    out=[[color if (r,c) in solid else bg for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    remaining=list(chosen)
    for hole in holes(target):
     unfilled=set(hole)
     while unfilled:
      r,c=min(unfilled); placed=False
      for i,o in enumerate(remaining):
       a,b,d,e=o['box']; shape={(x-a,y-b) for x,y in o['cells']}
       if all((r+x,c+y) in unfilled for x,y in shape):
        for x,y in shape: out[r+x-r0][c+y-c0]=o['color']
        unfilled-={(r+x,c+y) for x,y in shape}; remaining.pop(i); placed=True; break
      if not placed: raise ValueError('Cannot tile hole')
    return out
